def backfill_receipts(apps, schema_editor):
    """Give every ZEC purchase the old code already saw a receipt.

    WITHOUT THIS THE FIRST POST-DEPLOY CYCLE RE-CREDITS EVERY HISTORICAL
    PURCHASE. The old idempotency marker was the `g12f_transaction` row
    itself; the new one is `tuzis_zeccreditreceipt`. An empty receipt table
    means "nothing has ever been credited", which is false and expensive.

    A backfilled receipt asserts exactly one thing: *the old code already
    processed this note, so do not process it again.* It is NOT evidence that
    2Z were ever issued for it — the whole point of #1132(a) is that the old
    code could mark a note processed and then die before crediting. Those rows
    are flagged `backfilled=True` and `manage.py audit_zec_credits` lists the
    ones with no matching BOUGHT_TUZI event, which is the reconciliation the
    audit asked for.

    `output_index=0` for every backfilled row is correct for the data that
    exists: `txid` was the primary key, so history physically cannot contain
    two notes of the same transaction.
    """
    Transaction = apps.get_model('g12f', 'Transaction')
    ZecCreditReceipt = apps.get_model('tuzis', 'ZecCreditReceipt')

    rows = (
        Transaction.objects
        .filter(action='buy_2z')
        .values_list('txid', 'creator_id', 'amount')
        .iterator(chunk_size=_BATCH)
    )
    batch = []
    for txid, creator_id, amount in rows:
        batch.append(ZecCreditReceipt(
            txid=txid,
            output_index=0,
            pool='',
            creator_id=creator_id,
            amount_zec=amount,
            # The rate used at the time was never recorded, so these stay
            # NULL rather than being invented from today's price.
            tuzis_credited=None,
            tuzis_per_zec=None,
            backfilled=True,
        ))
        if len(batch) >= _BATCH:
            ZecCreditReceipt.objects.bulk_create(batch)
            batch = []
    if batch:
        ZecCreditReceipt.objects.bulk_create(batch)


